}
@media (prefers-reduced-motion: reduce) {
  .ah-glossary-wrapper .az-letter, .ah-glossary-wrapper .glossary-card, .auto-glossary-link, #glossary-tooltip { transition: none; }
  #glossary-tooltip, #glossary-tooltip.visible { transform: none; }
}
@media print {
  .auto-glossary-link { padding: 0; border: 0; background: transparent; color: inherit; text-decoration: none; }
  #glossary-tooltip, .ah-glossary-wrapper .az-navigation { display: none !important; }
  .ah-glossary-wrapper .glossary-card { box-shadow: none; break-inside: avoid; }
}
