/* Dark Theme Overrides */
[data-theme="dark"], body.dark-mode, .dark-theme {
  --bg: #0f172a;
  --text: #f1f5f9;
  --primary: #38bdf8;
  --surface: #1e293b;
  --border: #334155;
  --bg-dark-card: #1e293b;
  --bg-dark-callout: #0f172a;
  --border-dark-card: #334155;
  --text-dark-primary: #f8fafc;
  --text-dark-secondary: #cbd5e1;
  --text-dark-muted: #94a3b8;
}
[data-theme="dark"] body, body.dark-mode { background-color: var(--bg); color: var(--text); }
[data-theme="dark"] main, .dark-mode main, [data-theme="dark"] .layout, .dark-mode .layout, [data-theme="dark"] .post-body, .dark-mode .post-body, [data-theme="dark"] article, .dark-mode article, [data-theme="dark"] #main-wrapper, .dark-mode #main-wrapper, [data-theme="dark"] .post, .dark-mode .post, [data-theme="dark"] .widget.Blog, .dark-mode .widget.Blog { background-color: #0f172a !important; color: #f1f5f9 !important; }
[data-theme="dark"] .site-footer, .dark-mode .site-footer { background: #020617; }
