[data-theme="dark"] .post-body p, .dark-mode .post-body p, [data-theme="dark"] .post-body p span, .dark-mode .post-body p span, [data-theme="dark"] .post-body ul li, .dark-mode .post-body ul li, [data-theme="dark"] .post-body ol li, .dark-mode .post-body ol li { color: #e2e8f0 !important; }
