[data-theme="dark"] .sources-box h2, [data-theme="dark"] .sources-box h3, body.dark-mode .sources-box h2, body.dark-mode .sources-box h3 { color: #f8fafc !important; }
[data-theme="dark"] .sources-list li, body.dark-mode .sources-list li { color: #cbd5e1 !important; }
[data-theme="dark"] .sources-box a, body.dark-mode .sources-box a { color: #38bdf8 !important; border-bottom-color: #0284c7 !important; }
[data-theme="dark"] .sources-box a:hover, body.dark-mode .sources-box a:hover { color: #7dd3fc !important; }
[data-theme="dark"] .cookie-banner, body.dark-mode .cookie-banner { background: #1e293b !important; color: #f8fafc !important; border-color: #334155 !important; border-left-color: #38bdf8 !important; box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4) !important; }
[data-theme="dark"] .cookie-content a, body.dark-mode .cookie-content a { color: #38bdf8 !important; }
[data-theme="dark"] .cookie-btn, body.dark-mode .cookie-btn { background: #0284c7 !important; }
[data-theme="dark"] .cookie-btn:hover, body.dark-mode .cookie-btn:hover { background: #38bdf8 !important; color: #0f172a !important; }
[data-theme="dark"] #back-to-top, body.dark-mode #back-to-top { background: #1e293b !important; border-color: #334155 !important; color: #38bdf8 !important; box-shadow: 0 4px 14px rgba(0, 0, 0, 0.4) !important; }
[data-theme="dark"] #back-to-top:hover, body.dark-mode #back-to-top:hover { background: #0f172a !important; border-color: #38bdf8 !important; color: #7dd3fc !important; }
[data-theme="dark"] .ah-auto-toc, body.dark-mode .ah-auto-toc, [data-theme="dark"] .ah-article-glossary div[id^="term-"], body.dark-mode .ah-article-glossary div[id^="term-"], [data-theme="dark"] .ah-faq-section details, body.dark-mode .ah-faq-section details { background-color: #1e293b !important; border-color: #334155 !important; color: #e2e8f0 !important; }
[data-theme="dark"] .ah-auto-toc summary, body.dark-mode .ah-auto-toc summary, [data-theme="dark"] .ah-article-glossary dt, body.dark-mode .ah-article-glossary dt, [data-theme="dark"] .ah-faq-section summary, body.dark-mode .ah-faq-section summary { color: #38bdf8 !important; }
[data-theme="dark"] .ah-article-glossary dd, body.dark-mode .ah-article-glossary dd, [data-theme="dark"] .ah-faq-section details p, body.dark-mode .ah-faq-section details p { color: #cbd5e1 !important; }
[data-theme="dark"] div.post-body div div { background-color: #0f172a; color: #e2e8f0; }
[data-theme="dark"] tbody tr td { background-color: #1e293b; color: #e2e8f0; border-color: #334155; }
[data-theme="dark"] div.post-body div p { background-color: #0f172a; color: #e2e8f0; }
[data-theme="dark"] ul li a { color: #38bdf8; }
[data-theme="dark"] ul li a:hover { color: #7dd3fc; }
[data-theme="dark"] div.eeat-author-content p { color: #cbd5e1; }
[data-theme="dark"] div.eeat-author-content h3 { color: #fbbf24; }
[data-theme="dark"] aside.author-disclaimer-box { background-color: #1e293b; border: 1px solid #334155; }
[data-theme="dark"] aside.author-disclaimer-box p { color: #cbd5e1; }
[data-theme="dark"] aside.author-disclaimer-box h3 { background-color: #92400e; color: #fef3c7; }
[data-theme="dark"] nav.breadcrumb { background-color: #1e293b; color: #cbd5e1; border: 1px solid #334155; }
span.current-crumbs-title { background-color: transparent; color: #f8fafc; }
/* Media Queries & Responsive Layout */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; scroll-behavior: auto !important; }
  .post-card:hover, .related-card:hover, .compare-card:hover, .search-form:hover { transform: none !important; }
}
@media (max-width: 768px) {
  .sources-box { padding: 1.25rem; }
  .sources-box h2, .sources-box h3 { font-size: 1.25rem; }
  .sources-list li { font-size: 1rem; line-height: 1.7; }
  .cookie-banner { left: 10px; right: 10px; bottom: 10px; max-width: none; padding: 14px; }
}
@media (min-width: 768px) {
  .post-grid, #related-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (min-width: 1024px) {
  .layout { flex-direction: row; align-items: flex-start; }
  main { flex: 3; }
  aside, .sidebar { flex: 1; min-width: 300px; max-width: 380px; position: sticky; top: calc(var(--nav-height) + 20px); }
  .post-grid, #related-grid { grid-template-columns: repeat(3, 1fr); }
  .container { padding: 25px; }
}
@media (min-width: 1280px) {
  .post-grid, #related-grid { grid-template-columns: repeat(4, 1fr); }
}
a:focus-visible, button:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible, summary:focus-visible, [role="button"]:focus-visible {
  outline: 3px solid #f59e0b;
