function createScholarlyArticleSchema({ title, authors = [], year, journal, pmid, pmcid, doi }) {
  const formattedPmcid = pmcid ? (pmcid.toUpperCase().startsWith('PMC') ? pmcid.toUpperCase() : `PMC${pmcid}`) : null;
  const cleanPmid = pmid ? String(pmid).replace(/\D/g, '') : null;
  const sameAsUrls = [];
  if (formattedPmcid) {
    sameAsUrls.push(`https://www.ncbi.nlm.nih.gov/pmc/articles/${formattedPmcid}/`);
  }
  if (cleanPmid) {
    sameAsUrls.push(`https://pubmed.ncbi.nlm.nih.gov/${cleanPmid}/`);
  }
  if (doi) {
    const cleanDoi = doi.replace(/^https?:\/\/doi\.org\//, '');
    sameAsUrls.push(`https://doi.org/${cleanDoi}`);
  }
  const schema = {
    "@context": "https://schema.org",
    "@type": "ScholarlyArticle",
    "name": title
  };
  if (authors.length > 0) {
    schema.author = authors.map(name => ({
      "@type": "Person",
      "name": name
    }));
  }
  if (year) {
    schema.datePublished = String(year);
  }
  if (journal) {
    schema.isPartOf = {
      "@type": "PublicationIssue",
      "isPartOf": {
        "@type": "Periodical",
        "name": journal
      }
    };
  }
  if (sameAsUrls.length > 0) {
    schema.sameAs = sameAsUrls;
  }
  return schema;
}
