body.script:
//
document.addEventListener("DOMContentLoaded", async function() {
  const post = document.getElementById("post-body") || document.querySelector(".post-body");
  if (!post) return;
  const safe = (fn, name) => {
    try { fn(); } catch (e) { console.warn(name, e); }
  };
  // --- TABLE OF CONTENTS (Collapsible <details>, skips if post already has one) ---
  safe(() => {
    if (post.querySelector(".ah-auto-toc")) return;
    const headings = post.querySelectorAll("h2, h3");
    if (headings.length < 3) return;
    const d = document.createElement("details");
    d.className = "ah-auto-toc";
    d.style.cssText = "background:#f8fafc;border:1px solid #cbd5e1;border-radius:8px;padding:12px 18px;margin:0 0 22px 0;";
    const summary = document.createElement("summary");
    summary.textContent = "In This Article (Table of Contents)";
    summary.style.cssText = "font-weight:700;color:#1e3a8a;cursor:pointer;";
    d.appendChild(summary);
    const list = document.createElement("ul");
    list.style.cssText = "margin:10px 0 0 0;padding-left:20px;line-height:1.65;";
    headings.forEach(el => {
      if (!el.id) {
        el.id = el.textContent.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
      }
      const li = document.createElement("li");
      if (el.tagName === "H3") li.style.marginLeft = "16px";
      const a = document.createElement("a");
      a.textContent = el.textContent.trim();
      a.href = "#" + el.id;
      li.appendChild(a);
      list.appendChild(li);
    });
    d.appendChild(list);
    post.prepend(d);
  }, "TOC");
  // --- READING TIME ---
  safe(() => {
    const el = document.querySelector(".reading-time");
    if (!el) return;
    const words = (post.innerText || "").trim().split(/\s+/).filter(Boolean).length;
    if (words > 0) {
      el.textContent = Math.max(1, Math.ceil(words / 200)) + " min read";
    }
  }, "Reading Time");
  // --- RELATED POSTS (ASYNC FETCH) ---
  const grid = document.getElementById("related-grid");
  if (grid) {
    try {
      const res = await fetch("/feeds/posts/default?alt=json&max-results=8");
      if (res.ok) {
        const data = await res.json();
        const entries = (data && data.feed && data.feed.entry) ? data.feed.entry : [];
        let html = "";
        let count = 0;
        for (const e of entries) {
          if (count >= 4) break;
          let url = "#";
          let img = "";
          (e.link || []).forEach(l => {
            if (l.rel === "alternate") url = l.href;
          });
          if (e.media$thumbnail && e.media$thumbnail.url) {
            img = e.media$thumbnail.url.replace(/\/s\d+(-c)?\//, "/w400-h250-c/");
          }
          if (url !== "#" && url.replace(/\?m=1$/, "") !== location.href.replace(/\?m=1$/, "")) {
            const title = (e.title && e.title.$t) ? e.title.$t : "Read Article";
            html += '<a class="related-card" href="' + url + '">' +
              (img ? '<img src="' + img + '" alt="' + title.replace(/"/g, "&quot;") + '" width="400" height="250" loading="lazy" />' : '') +
              '<span class="related-card-title">' + title + '</span>' +
            '</a>';
            count++;
          }
        }
        grid.innerHTML = html || "<p>Explore more guides in the archive above.</p>";
      }
    } catch (e) {
      console.warn("Related Posts failed:", e);
    }
  }
});
