(function() {
  function initFooterTools() {
    var images = document.getElementsByTagName("img");
    for (var i = 0; i < images.length; i++) {
      if (!images[i].getAttribute("alt") || images[i].getAttribute("alt").trim() === "") {
        var imgTitle = images[i].getAttribute("title");
        images[i].setAttribute("alt", imgTitle ? imgTitle : "Aging Health Management Content Image");
      }
    }
    var btn = document.getElementById("back-to-top");
    if (!btn) return;
    var scrollContainer = document.scrollingElement || document.documentElement || document.body;
    function toggleVisibility() {
      var offset = window.pageYOffset || scrollContainer.scrollTop || 0;
      if (offset > 250) {
        btn.classList.add("is-visible");
        btn.style.display = "flex";
      } else {
        btn.classList.remove("is-visible");
        btn.style.display = "none";
      }
    }
    toggleVisibility();
    window.addEventListener("scroll", toggleVisibility, { passive: true });
    btn.addEventListener("click", function() {
      window.scrollTo({ top: 0, behavior: "smooth" });
    });
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initFooterTools);
  } else {
    initFooterTools();
  }
})();
