(function() {
  var trackingLoaded = false;
  var CONSENT_KEY = 'aginghealth_cookie_consent';
  // 1. Core Loader for Analytics & Tracking Scripts
  function loadTrackingScripts() {
    if (trackingLoaded) return;
    trackingLoaded = true;
    // Clean up interaction event listeners
    ['keydown', 'touchmove', 'touchstart', 'mousemove', 'scroll'].forEach(function(ev) {
      window.removeEventListener(ev, loadTrackingScripts, { passive: true });
    });
    // Load Google Analytics (gtag.js)
    var gaScript = document.createElement('script');
    gaScript.async = true;
    gaScript.src = 'https://www.googletagmanager.com/gtag/js?id=G-YOUR_MEASUREMENT_ID';
    document.head.appendChild(gaScript);
    window.dataLayer = window.dataLayer || [];
    function gtag(){ dataLayer.push(arguments); }
    window.gtag = gtag;
    gtag('js', new Date());
    gtag('config', 'G-YOUR_MEASUREMENT_ID');
    // Load Microsoft Clarity
    (function(c,l,a,r,i,t,y){
        c[a]=c[a]||function(){(c[a].q=c[a].q||[]).push(arguments)};
        t=l.createElement(r);t.async=1;t.src="https://www.clarity.ms/tag/"+i;
        y=l.getElementsByTagName(r)[0];y.parentNode.insertBefore(t,y);
    })(window, document, "clarity", "script", "YOUR_CLARITY_PROJECT_ID");
  }
  // 2. Initialize Tracking Engine on Interaction
  function initLazyTracking() {
    ['keydown', 'touchmove', 'touchstart', 'mousemove', 'scroll'].forEach(function(ev) {
      window.addEventListener(ev, loadTrackingScripts, { passive: true });
    });
    // Fallback timer for background/bounce traffic once consented
    setTimeout(loadTrackingScripts, 5000);
  }
  // 3. Cookie Banner DOM & Consent Controller
  document.addEventListener('DOMContentLoaded', function() {
    var consentStatus = localStorage.getItem(CONSENT_KEY);
    var banner = document.getElementById('cookie-banner');
    var acceptBtn = document.getElementById('cookie-accept-btn');
    if (consentStatus === 'granted') {
      // User previously accepted: start lazy-loading listeners
      initLazyTracking();
    } else if (consentStatus !== 'denied') {
      // No decision stored: show banner
      if (banner) banner.classList.add('is-visible');
    }
    if (acceptBtn) {
      acceptBtn.addEventListener('click', function() {
        localStorage.setItem(CONSENT_KEY, 'granted');
        if (banner) banner.classList.remove('is-visible');
        // Trigger tracking setup immediately upon acceptance
        initLazyTracking();
        loadTrackingScripts();
      });
    }
  });
})();
