(function () {
  "use strict";
  const DATABASE_PATH = "/p/glossary-data-hidden.html";
  const GLOSSARY_PAGE_PATH = "/p/glossary.html";
  const EXCLUDED = [
    "a",
    "h1", "h2", "h3", "h4", "h5", "h6",
    "button", "pre", "code",
    "script", "style", "noscript", "template",
    "textarea", "select", "option",
    "svg", "math",
    "[contenteditable]:not([contenteditable='false'])",
    "[data-no-glossary]",
    "#glossary-database",
    "#glossary-container",
    ".ah-article-glossary",
    ".caption", ".sidebar", ".breadcrumbs"
  ].join(",");
  function escapeRegExp(value) {
    return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }
  // Canonicalizes apostrophes and trailing 's' so variants resolve to the same entry
  function canonicalKey(value) {
    return value
      .trim()
      .toLowerCase()
      .replace(/['’]/g, "")
      .replace(/s\b/g, "");
  }
  // Matches the exact slug generator used on /p/glossary.html
  function slugifyTerm(term) {
    return term
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "");
  }
  // Builds a regex pattern that allows optional straight/curly apostrophes and optional plural 's'
  function buildTermPattern(term) {
    const clean = term.trim().replace(/['’]/g, "");
    const words = clean.split(/\s+/).map(function (word, index, arr) {
      const isLastWord = index === arr.length - 1;
      // Allow optional apostrophe before a trailing 's' (e.g., Alzheimers -> Alzheimer['’]?s?)
      if (/s$/i.test(word) && word.length > 3) {
        const stem = escapeRegExp(word.slice(0, -1));
        return stem + "['’]?s?";
      }
      // Allow optional plural 's' on the final word (e.g., screening -> screenings)
      if (isLastWord && word.length > 3 && !/[sxz]$/i.test(word)) {
        return escapeRegExp(word) + "s?";
      }
      return escapeRegExp(word);
    });
    return words.join("\\s+");
  }
  function isCurrentPage(url) {
    return (
      location.origin === url.origin &&
      location.pathname.replace(/\/+$/, "") === url.pathname.replace(/\/+$/, "")
    );
  }
  async function fetchDocument(url) {
    const response = await fetch(url.href, { credentials: "same-origin" });
    if (!response.ok) {
      throw new Error("Request failed: HTTP " + response.status + " for " + url.pathname);
    }
    return new DOMParser().parseFromString(await response.text(), "text/html");
  }
  function extractDefinition(entry) {
    const attrDef = entry.getAttribute("data-definition");
    if (attrDef && attrDef.trim()) return attrDef.trim();
    const defEl = entry.querySelector(".glossary-definition, .definition, p, dd");
    if (defEl && defEl.textContent.trim()) return defEl.textContent.trim();
    const clone = entry.cloneNode(true);
    const heading = clone.querySelector(".glossary-term, h2, h3, h4, dt, strong");
    if (heading) heading.remove();
    return clone.textContent.replace(/\s+/g, " ").trim();
  }
  function injectArticleGlossarySchema(matchedItems, glossaryPageUrl) {
    if (!matchedItems || !matchedItems.length) return;
    const glossarySetId = glossaryPageUrl + "#glossary-hub";
    const canonicalEl = document.querySelector("link[rel='canonical']");
    const canonicalUrl = canonicalEl && canonicalEl.href
      ? canonicalEl.href
      : location.origin + location.pathname;
    const schemaGraph = {
      "@context": "https://schema.org",
      "@graph": [
        {
          "@type": "DefinedTermSet",
          "@id": glossarySetId,
          "name": "Aging Health Medical & Senior Wellness Glossary",
          "url": glossaryPageUrl
        },
        {
          "@type": "MedicalWebPage",
          "@id": canonicalUrl + "#webpage",
          "url": canonicalUrl,
          "mentions": matchedItems.map(function (item) {
            const termNode = {
              "@type": "DefinedTerm",
              "@id": item.url,
              "name": item.term,
              "url": item.url,
              "inDefinedTermSet": { "@id": glossarySetId }
            };
            if (item.definition) {
              termNode.description = item.definition;
            }
            return termNode;
          })
        }
      ]
    };
    const existing = document.getElementById("ah-dynamic-glossary-schema");
    if (existing) existing.remove();
    const script = document.createElement("script");
    script.id = "ah-dynamic-glossary-schema";
    script.type = "application/ld+json";
    script.textContent = JSON.stringify(schemaGraph);
    document.head.appendChild(script);
  }
  async function linkGlossary() {
    const article = document.querySelector(".post-body, .entry-content, .post-content, article");
    if (!article || article.dataset.glossaryLinker) return;
    const databaseURL = new URL(DATABASE_PATH, location.origin);
    const glossaryURL = new URL(GLOSSARY_PAGE_PATH, location.origin);
    if (isCurrentPage(databaseURL) || isCurrentPage(glossaryURL)) {
      return;
    }
    article.dataset.glossaryLinker = "loading";
    try {
      const databaseDocument = await fetchDocument(databaseURL);
      const termsByKey = new Map();
      const entries = databaseDocument.querySelectorAll(
        "#glossary-database .glossary-entry[data-term], .glossary-entry[data-term]"
      );
      for (const entry of entries) {
        const term = (entry.getAttribute("data-term") || "").trim();
        if (!term) continue;
        const key = canonicalKey(term);
        if (termsByKey.has(key)) continue;
        const destination = new URL(glossaryURL.href);
        destination.hash = slugifyTerm(term);
        termsByKey.set(key, {
          term: term,
          pattern: buildTermPattern(term),
          url: destination.href,
          definition: extractDefinition(entry)
        });
      }
      const terms = Array.from(termsByKey.values()).sort(
        (a, b) => b.term.length - a.term.length
      );
      if (!terms.length) {
        throw new Error("No glossary entries found in " + DATABASE_PATH);
      }
      const alternatives = terms.map(item => item.pattern).join("|");
      const regex = new RegExp(
        "(^|[^\\p{L}\\p{N}_])(" + alternatives + ")(?=$|[^\\p{L}\\p{N}_])",
        "giu"
      );
      const linked = new Set();
      const matchedItems = [];
      for (const anchor of article.querySelectorAll("a.auto-glossary-link[data-term]")) {
        const existingKey = canonicalKey(anchor.getAttribute("data-term") || "");
        if (existingKey && !linked.has(existingKey)) {
          linked.add(existingKey);
          const existingItem = termsByKey.get(existingKey);
          if (existingItem) matchedItems.push(existingItem);
        }
      }
      const walker = document.createTreeWalker(
        article,
        NodeFilter.SHOW_TEXT,
        {
          acceptNode: function (node) {
            const parent = node.parentElement;
            if (!parent || !node.nodeValue.trim() || parent.closest(EXCLUDED)) {
              return NodeFilter.FILTER_REJECT;
            }
            return NodeFilter.FILTER_ACCEPT;
          }
        }
      );
      const nodes = [];
      while (walker.nextNode()) {
        nodes.push(walker.currentNode);
      }
      for (const node of nodes) {
        if (!article.contains(node)) continue;
        const text = node.nodeValue;
        const fragment = document.createDocumentFragment();
        let cursor = 0;
        let changed = false;
        let match;
        regex.lastIndex = 0;
        while ((match = regex.exec(text)) !== null) {
          const matchedText = match[2];
          const key = canonicalKey(matchedText);
          const item = termsByKey.get(key);
          if (!item || linked.has(key)) continue;
          const start = match.index + match[1].length;
          const end = start + matchedText.length;
          fragment.appendChild(document.createTextNode(text.slice(cursor, start)));
          const anchor = document.createElement("a");
          anchor.className = "auto-glossary-link";
          anchor.setAttribute("data-term", item.term);
          anchor.href = item.url;
          anchor.title = item.definition
            ? item.term + ": " + item.definition
            : "View definition in Aging Health Glossary";
          anchor.textContent = matchedText;
          fragment.appendChild(anchor);
          linked.add(key);
          matchedItems.push(item);
          cursor = end;
          changed = true;
        }
        if (changed) {
          fragment.appendChild(document.createTextNode(text.slice(cursor)));
          node.parentNode.replaceChild(fragment, node);
        }
      }
      injectArticleGlossarySchema(matchedItems, glossaryURL.href);
      article.dataset.glossaryLinker = "done";
    } catch (error) {
      delete article.dataset.glossaryLinker;
      console.warn("Glossary linker error:", error);
    }
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", linkGlossary, { once: true });
  } else {
    linkGlossary();
  }
})();
