(function() {
  // 1. Apply saved theme immediately and define toggleTheme globally
  function applyTheme(theme) {
    document.documentElement.setAttribute("data-theme", theme);
    if (document.body) {
      document.body.classList.toggle("dark-mode", theme === "dark");
    }
    localStorage.setItem("theme", theme);
    var btn = document.getElementById("theme-toggle") || document.querySelector("[onclick*='toggleTheme'], .theme-toggle");
    if (btn) {
      btn.textContent = theme === "dark" ? "☀️" : "🌙";
      btn.setAttribute("aria-label", theme === "dark" ? "Switch to light mode" : "Switch to dark mode");
    }
  }
  window.toggleTheme = function() {
    var current = document.documentElement.getAttribute("data-theme") === "dark" ? "dark" : "light";
    applyTheme(current === "dark" ? "light" : "dark");
  };
  // Sync saved preference on initial load and once <body> is ready
  var savedTheme = localStorage.getItem("theme") || "light";
  document.documentElement.setAttribute("data-theme", savedTheme);
  document.addEventListener("DOMContentLoaded", function() {
    applyTheme(localStorage.getItem("theme") || "light");
    // Fallback click listener in case the button lacks an inline onclick="toggleTheme()"
    var btn = document.getElementById("theme-toggle") || document.querySelector(".theme-toggle, #dark-mode-toggle");
    if (btn && !btn.getAttribute("onclick")) {
      btn.addEventListener("click", window.toggleTheme);
    }
  });
  // Clean ?m=1 mobile parameter from URL bar
  if (location.search === "?m=1") {
    history.replaceState(null, "", location.pathname + location.hash);
  }
})();
